class Shape {
public:
    // Virtual function enables dynamic binding
    virtual void draw() const = 0;
    // Essential for safe deletion of derived objects
    virtual ~Shape() = default;
};

class Circle : public Shape {
public:
    void draw() const override {}
};

// Polymorphic invocation
Shape* s = new Circle();
s->draw(); // Dynamically calls Circle::draw()

delete s; // Uses virtual destructor (if present)
